package alphametics

import (
	"errors"
	"strings"
)

func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, "==")
	if len(eq) != 2 {
		return nil, errors.New("invalid puzzle")
	}
	terms := strings.Split(eq[0], "+")
	result := strings.TrimSpace(eq[1])
	terms = append(terms, result)

	coeff := map[string]int{}
	leading := map[string]bool{}
	for i, term := range terms {
		term = strings.TrimSpace(term)
		if len(term) > 1 {
			leading[term[:1]] = true
		}
		sign := 1
		if i == len(terms)-1 {
			sign = -1
		}
		for j := len(term) - 1; j >= 0; j-- {
			c := term[j : j+1]
			coeff[c] += sign * pow10(len(term)-1-j)
		}
	}

	letters := make([]string, 0, len(coeff))
	for c := range coeff {
		letters = append(letters, c)
	}

	assign := map[string]int{}
	used := map[int]bool{}

	var solve func(idx int) bool
	solve = func(idx int) bool {
		if idx == len(letters) {
			for c, k := range coeff {
				if k != 0 && k != assign[c] {
					return false
				}
			}
			return true
		}
		c := letters[idx]
		for d := 0; d <= 9; d++ {
			if used[d] {
				continue
			}
			if leading[c] && d == 0 {
				continue
			}
			assign[c] = d
			used[d] = true
			if solve(idx + 1) {
				return true
			}
			used[d] = false
			delete(assign, c)
		}
		return false
	}

	if !solve(0) {
		return nil, errors.New("puzzle has no solution")
	}
	return assign, nil
}
```

