package alphametics

import (
	"errors"
	"strings"
)

// Solve solves an alphametics puzzle of the form
// "WORD1 + WORD2 + ... == RESULT", assigning each letter a distinct digit so
// that the equation holds. Leading letters of multi-digit words may not be
// zero. It returns the letter-to-digit mapping, or an error if no solution
// exists.
func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, "==")
	if len(eq) != 2 {
		return nil, errors.New("invalid puzzle: expected exactly one '=='")
	}

	terms := strings.Split(eq[0], "+")
	terms = append(terms, eq[1])

	coeff := map[string]int{}
	leading := map[string]bool{}
	for i, term := range terms {
		term = strings.TrimSpace(term)
		if len(term) > 1 {
			leading[term[:1]] = true
		}
		sign := 1
		if i == len(terms)-1 {
			sign = -1 // the result is subtracted
		}
		for j := len(term) - 1; j >= 0; j-- {
			coeff[term[j:j+1]] += sign * pow10(len(term) - 1 - j)
		}
	}

	letters := make([]string, 0, len(coeff))
	for c := range coeff {
		letters = append(letters, c)
	}

	assign := map[string]int{}
	used := map[int]bool{}

	var solve func(idx int) bool
	solve = func(idx int) bool {
		if idx == len(letters) {
			sum := 0
			for c, k := range coeff {
				sum += k * assign[c]
			}
			return sum == 0
		}
		c := letters[idx]
		for d := 0; d <= 9; d++ {
			if used[d] {
				continue
			}
			if leading[c] && d == 0 {
				continue
			}
			assign[c] = d
			used[d] = true
			if solve(idx + 1) {
				return true
			}
			used[d] = false
			delete(assign, c)
		}
		return false
	}

	if !solve(0) {
		return nil, errors.New("puzzle has no solution")
	}
	return assign, nil
}

func pow10(n int) int {
	p := 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}
